INSERT INTO Servicio (id_sede, mes_servicio, fecha_ejecucion, descripcion_residuo, forma_pago, observaciones, estado_pago, fecha_pago, estado)
SELECT se.id_sede, 'OCTUBRE', '2020-10-23', 'GESTION DE RR.SS', 'TRANSFERENCIA', NULL, 'pagado', '2020-10-23', 'completado'
FROM Sede se
INNER JOIN Empresa e ON se.id_empresa = e.id_empresa
WHERE e.ruc = '20511944202'
LIMIT 1;

